// Retain only complete JSON story blocks already generated by the model.
// Never guess missing prose, close a partial string or apply partial effects.
export function recoverCompletedBlocks(raw) {
  if (typeof raw !== 'string' || raw.length > 26000) return null;
  const match = /"blocks"\s*:\s*\[/.exec(raw);
  if (!match) return null;
  const blocks = []; let depth = 0, start = -1, quoted = false, escaped = false;
  for (let i = match.index + match[0].length; i < raw.length; i++) {
    const char = raw[i];
    if (quoted) {
      if (escaped) escaped = false;
      else if (char === '\\') escaped = true;
      else if (char === '"') quoted = false;
      continue;
    }
    if (char === '"') quoted = true;
    else if (char === '{') { if (!depth) start = i; depth++; }
    else if (char === '}' && depth) {
      if (--depth === 0) {
        try {
          const block = JSON.parse(raw.slice(start, i + 1));
          if (!['narr', 'dlg', 'sys'].includes(block.type) || typeof block.text !== 'string' || !block.text.trim()) break;
          blocks.push(block);
        } catch { break; }
      }
    } else if (char === ']' && !depth) break;
    if (blocks.length >= 8) break;
  }
  return blocks.some(b => b.type === 'narr' && b.text.length >= 20) ? blocks : null;
}
